questions.solution:
function paidTotals(payments) {
  return payments
    .filter((p) => p.status === "paid")
    .reduce((n, p) => n + p.amount, 0);
}

function groupCount(rows, status) {
  return rows.reduce((n, row) => n + (row.status === status ? 1 : 0), 0);
}
